export const EMAIL_LOGO_CID = 'iceland-taxi-logo'
export const EMAIL_LOGO_SRC = 'cid:iceland-taxi-logo'
const PNG_BASE64 = ''
export function emailLogoAttachment() {
  return { filename: 'logo.png', content: Buffer.from(PNG_BASE64, 'base64'), cid: EMAIL_LOGO_CID, contentType: 'image/png' as const, contentDisposition: 'inline' as const }
}
